WITH src AS (SELECT * FROM payments WHERE paid_at < '2025-08-06' AND method = 'cash'), amount_bucket_summary AS (SELECT CASE WHEN amount >= 1700 THEN 'high' WHEN amount >= 370 THEN 'mid' ELSE 'low' END AS amount_bucket, MAX(paid_at) AS last_paid_at FROM src GROUP BY CASE WHEN amount >= 1700 THEN 'high' WHEN amount >= 370 THEN 'mid' ELSE 'low' END) SELECT amount_bucket, last_paid_at FROM amount_bucket_summary ORDER BY amount_bucket
